import subprocess, sys, os
sys.path.insert(0, '/workspace/dev')
import topo

def all_specs():
    specs = []
    for k in range(4, 19, 2):
        if k*k <= 343:
            for scope in ('tor', 'pod'):
                for intra in (0, 1):
                    specs.append(['clos', k, scope, intra])
    ls = []
    for leaves in range(2, 257):
        for spines in range(1, 257):
            if leaves+spines <= 343: ls.append(['leaf-spine', leaves, spines])
    step = max(1, len(ls)//60)
    specs.extend(ls[::step])
    for n in range(3, 19):
        if n*n <= 343:
            specs.append(['torus2d', n, 'host']); specs.append(['torus2d', n, 'row'])
    for n in range(3, 8):
        if n**3 <= 343:
            specs.append(['torus3d', n, 'host']); specs.append(['torus3d', n, 'line'])
    df = []
    for g in range(2, 344):
        for a in range(1, 344):
            if g*a > 343: break
            for h in range(1, 65):
                if g-1 == a*h:
                    for scope in ('router', 'group', 'target'): df.append(['dragonfly', g, a, h, scope])
    specs.extend(df)
    dp = []
    for g in range(2, 172):
        for l in range(1, 172):
            for s in range(1, 172):
                if g*(l+s) > 343: break
                for h in range(1, 65):
                    if g-1 == s*h:
                        for scope in ('group', 'tor'): dp.append(['dragonfly-plus', g, l, s, h, 0, scope])
                        break
                if g*(l+s) <= 343:
                    for scope in ('group', 'tor'): dp.append(['dragonfly-plus', g, l, s, 1, 1, scope])
    step = max(1, len(dp)//150)
    specs.extend(dp[::step])
    return specs

def main():
    lo, hi = int(sys.argv[1]), int(sys.argv[2])
    specs = all_specs()[lo:hi]
    lines = '\n'.join(topo.spec_line(s) for s in specs) + '\n'
    proc = subprocess.run(['/workspace/dev/dump2'], input=lines, capture_output=True, text=True, check=True)
    rrows = proc.stdout.strip().split('\n')
    bad = 0
    with open('/workspace/dev/cmp2.log', 'a') as log:
        for spec, row in zip(specs, rrows):
            rn, rt, rh = row.split(' ')
            pn, pt, ph = topo.spec_hash(spec)
            ok = (int(rn) == pn and int(rt) == pt and rh == '%016x' % ph)
            if not ok:
                bad += 1
                log.write('MISMATCH %s rust=%s py=%d %d %016x\n' % (spec, row, pn, pt, ph))
        log.write('range %d..%d checked %d mismatches %d\n' % (lo, hi, len(specs), bad))
    print('range', lo, hi, 'specs', len(specs), 'mismatches', bad)
    print('total specs', len(all_specs()))

main()
PYEOF
cd /workspace/dev && rm -f cmp2.log && time python3 cmp2.py 0 120
